namespace SmartiePaws.Inventory.Core.Entities.Sales;

/// <summary>
/// An optional record of who a sale was made to. Most sales -- walk-ins, cash customers you
/// never get details from -- will have no Customer at all, which is expected:
/// <see cref="Sale.CustomerId"/> is nullable, and a Customer row only gets created when there's
/// actually some identifying information worth keeping.
/// </summary>
public class Customer
{
  /// <summary>
  /// Primary key. Generated by Postgres (<c>gen_random_uuid()</c>) on insert.
  /// </summary>
  public Guid Id { get; set; }

  /// <summary>
  /// Required if a Customer row exists at all -- a record with literally no name isn't useful
  /// for anything (a repeat-customer lookup, a receipt, etc.).
  /// </summary>
  public string Name { get; set; } = string.Empty;

  /// <summary>
  /// Contact email, if known.
  /// </summary>
  public string? Email { get; set; }

  /// <summary>
  /// Contact phone number, if known.
  /// </summary>
  public string? Phone { get; set; }

  /// <summary>
  /// Anything else worth remembering about this customer.
  /// </summary>
  public string? Notes { get; set; }

  /// <summary>
  /// UTC timestamp set by the database when this row was first inserted.
  /// </summary>
  public DateTimeOffset CreatedAt { get; set; }

  /// <summary>
  /// UTC timestamp set by the database on insert and advanced on every subsequent update.
  /// </summary>
  public DateTimeOffset UpdatedAt { get; set; }

  /// <summary>
  /// UTC timestamp of a soft delete. Null while the customer is active.
  /// </summary>
  public DateTimeOffset? DeletedAt { get; set; }
}
